package blockchain.contracts

import scala.util.matching.Regex
import scala.collection.mutable
import java.time.Instant
import java.security.MessageDigest

object ContractValidator {
  // Rate limiting configuration
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val WINDOW_SIZE_MS = 60000L
  private val MAX_RETRIES = 3
  private val RETRY_BACKOFF_MS = 500L

  // Request tracking for rate limiting
  private val requestLog = mutable.Map[String, mutable.Queue[(Long, Int)]]() 

  // Contract address validation pattern
  private val ADDRESS_PATTERN: Regex = """^0x[0-9a-fA-F]{40}$""".r

  // Contract metadata validation - validates key=value pairs in contract annotations
  // Supports nested groupings with balanced brackets
  private val METADATA_PATTERN: Regex = {
    val keyPart = """[a-zA-Z_][a-zA-Z0-9_]*"""
    val valuePart = """[^;]*"""
    val pairPattern = s"""($keyPart\\s*=\\s*$valuePart)"""
    new Regex(s"""^($pairPattern(;\\s*$pairPattern)*)$$""")
  }

  // ABI signature validation for function calls
  // Format: functionName(type1,type2,...) -> returnType
  private val ABI_SIGNATURE_PATTERN: Regex = {
    val typeExpr = """[a-zA-Z0-9\[\]]+"""
    val params = s"""($typeExpr(,\\s*$typeExpr)*|)"""
    val returnType = s"""$typeExpr"""
    new Regex(s"""^[a-zA-Z_][a-zA-Z0-9_]*\\($params\\)\\s*->\\s*$returnType$$""")
  }

  // Bytecode comment/annotation pattern for deployment verification
  // Matches: @annotation(param1, param2, ...)
  private val ANNOTATION_PATTERN: Regex = {
    // This pattern validates nested annotation parameters
    // Parameters can contain sub-expressions with balanced parens
    val paramContent = """[^)]*"""
    val annotName = """[a-zA-Z_][a-zA-Z0-9_]*"""
    new Regex(s"""^@$annotName\\(($paramContent(,\\s*$paramContent)*)\\)$$""")
  }

  // Transaction memo field validator
  // Memos can contain text with optional tags like <tag>content</tag>
  private val MEMO_PATTERN: Regex = {
    val tagContent = """[^<]*"""
    val tagName = """[a-z]+"""
    val tagExpr = s"""<$tagName>$tagContent</$tagName>"""
    val textOrTag = s"""($tagExpr|[^<]+)*"""
    new Regex(s"""^$textOrTag$$""")
  }

  case class ValidationResult(valid: Boolean, errors: List[String])
  case class ContractSubmission(
    address: String,
    metadata: String,
    abiSignatures: List[String],
    annotations: List[String],
    memo: String,
    submitterKey: String
  )

  def isRateLimited(submitterKey: String): Boolean = {
    val now = System.currentTimeMillis()
    val queue = requestLog.getOrElseUpdate(submitterKey, mutable.Queue.empty)

    // Purge old entries
    while (queue.nonEmpty && queue.front._1 < now - WINDOW_SIZE_MS) {
      queue.dequeue()
    }

    val totalRequests = queue.map(_._2).sum
    totalRequests >= MAX_REQUESTS_PER_WINDOW
  }

  def recordRequest(submitterKey: String, weight: Int = 1): Unit = {
    val now = System.currentTimeMillis()
    val queue = requestLog.getOrElseUpdate(submitterKey, mutable.Queue.empty)
    queue.enqueue((now, weight))
  }

  def computeHash(data: String): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.digest(data.getBytes("UTF-8")).map("%02x".format(_)).mkString
  }

  def validateWithRetry(submission: ContractSubmission, attempt: Int = 0): ValidationResult = {
    if (isRateLimited(submission.submitterKey)) {
      if (attempt < MAX_RETRIES) {
        Thread.sleep(RETRY_BACKOFF_MS * (attempt + 1))
        return validateWithRetry(submission, attempt + 1)
      }
      return ValidationResult(false, List("Rate limit exceeded after retries"))
    }

    recordRequest(submission.submitterKey, weight = 2)
    performValidation(submission)
  }

  def performValidation(submission: ContractSubmission): ValidationResult = {
    val errors = mutable.ListBuffer[String]()

    // Validate address format
    if (ADDRESS_PATTERN.findFirstIn(submission.address).isEmpty) {
      errors += s"Invalid contract address: ${submission.address.take(10)}..."
    }

    // Validate metadata - this is where user input hits the regex engine
    if (submission.metadata.nonEmpty) {
      if (METADATA_PATTERN.findFirstIn(submission.metadata).isEmpty) {
        errors += "Invalid metadata format"
      }
    }

    // Validate ABI signatures
    submission.abiSignatures.zipWithIndex.foreach { case (sig, idx) =>
      if (ABI_SIGNATURE_PATTERN.findFirstIn(sig).isEmpty) {
        errors += s"Invalid ABI signature at index $idx"
      }
    }

    // Validate annotations
    submission.annotations.foreach { annot =>
      if (ANNOTATION_PATTERN.findFirstIn(annot).isEmpty) {
        errors += s"Invalid annotation: ${annot.take(20)}..."
      }
    }

    // Validate memo field
    if (submission.memo.nonEmpty) {
      if (MEMO_PATTERN.findFirstIn(submission.memo).isEmpty) {
        errors += "Invalid memo format"
      }
    }

    // Compute submission hash for audit trail
    val submissionData = s"${submission.address}|${submission.metadata}|${submission.memo}"
    val hash = computeHash(submissionData)

    if (errors.isEmpty) {
      ValidationResult(true, List.empty)
    } else {
      ValidationResult(false, errors.toList)
    }
  }
}
